1: //! Pure passthrough D-Bus interfaces for the op-openvswitch-daemon.
2: //!
3: //! THREE D-Bus object paths (locked design):
4: //! - `/org/opdbus/rovs/jsonrpc`  → interface `org.opdbus.rovs.jsonrpc`
5: //! - `/org/opdbus/rovs/openflow` → interface `org.opdbus.rovs.openflow`
6: //! - `/org/opdbus/rovs/proxy`    → interface `org.opdbus.rovs.proxy`
7: //!
8: //! The daemon knows NOTHING about bridges, ports, or containers on the jsonrpc/openflow
9: //! paths.  It only proxies raw `rovs-jsonrpc` / `rovs-openflow` primitives over D-Bus.
10: //! Business logic lives in the consuming plugins.
11: //!
12: //! The `proxy` path provides the openvswitch proxy operations for container
13: //! network namespace management (attach/detach OVS internal ports).
14: 
15: use anyhow::{Context, Result};
16: use rovs_ovsdb::Client;
17: use rovs_transport::Address;
18: use std::collections::HashMap;
19: use std::sync::Arc;
20: use tokio::sync::Mutex;
21: use tracing::{debug, info, warn};
22: use zbus::interface;
23: 
24: // ── Shared daemon state ───────────────────────────────────────────────────────
25: 
26: /// Global state shared by both D-Bus objects.
27: #[derive(Clone)]
28: pub struct DaemonState {
29:     /// OVSDB JSON-RPC client (rovs_ovsdb).  Lazily initialised on first call.
30:     pub ovsdb: Arc<Mutex<Option<Client>>>,
31:     /// OVS Unix-domain socket path.
32:     pub socket_path: String,
33:     /// OpenFlow connections: conn_id → VConn.
34:     pub of_conns: Arc<Mutex<HashMap<u64, rovs_openflow::VConn>>>,
35:     /// Monotonic connection handle allocator.
36:     pub next_of_id: Arc<Mutex<u64>>,
37: }
38: 
39: impl DaemonState {
40:     pub fn new(socket_path: String) -> Self {
41:         Self {
42:             ovsdb: Arc::new(Mutex::new(None)),
43:             socket_path,
44:             of_conns: Arc::new(Mutex::new(HashMap::new())),
45:             next_of_id: Arc::new(Mutex::new(1)),
46:         }
47:     }
48: 
49:     /// Get or create the persistent OVSDB client.
50:     pub async fn get_ovsdb(&self) -> Result<tokio::sync::MutexGuard<'_, Option<Client>>> {
51:         let mut guard = self.ovsdb.lock().await;
52:         if guard.is_none() {
53:             let client = Client::connect(&format!("unix:{}", self.socket_path))
54:                 .await
55:                 .with_context(|| format!("connect to OVSDB at {}", self.socket_path))?;
56:             info!("OVSDB client connected to {}", self.socket_path);
57:             *guard = Some(client);
58:         }
59:         Ok(guard)
60:     }
61: 
62:     /// Allocate a new OpenFlow connection handle id.
63:     pub async fn alloc_of_id(&self) -> u64 {
64:         let mut n = self.next_of_id.lock().await;
65:         let id = *n;
66:         *n += 1;
67:         id
68:     }
69: }
70: 
71: // ── JSON-RPC object (/org/opdbus/rovs/jsonrpc) ──────────────────────────────
72: 
73: /// D-Bus service proxying raw `rovs-jsonrpc` + `rovs-ovsdb` primitives.
74: pub struct JsonRpcService {
75:     state: DaemonState,
76: }
77: 
78: impl JsonRpcService {
79:     pub fn new(state: DaemonState) -> Self {
80:         Self { state }
81:     }
82: }
83: 
84: #[interface(name = "org.opdbus.rovs.jsonrpc")]
85: impl JsonRpcService {
86:     /// Execute a raw OVSDB JSON-RPC `transact`.
87:     ///
88:     /// `method` — JSON-RPC method name (always `"transact"` for OVSDB).
89:     /// `params_json` — JSON-encoded params array (e.g. `["Open_vSwitch", {op:...}]`).
90:     /// Returns JSON-encoded result.
91:     async fn transact(&self, method: &str, params_json: &str) -> String {
92:         debug!(
93:             "jsonrpc.transact method={} params_len={}",
94:             method,
95:             params_json.len()
96:         );
97: 
98:         let mut guard = match self.state.get_ovsdb().await {
99:             Ok(g) => g,
100:             Err(e) => return json_error(&format!("OVSDB connect failed: {}", e)),
101:         };
102:         let client = match guard.as_mut() {
103:             Some(c) => c,
104:             None => return json_error("OVSDB client unavailable"),
105:         };
106: 
107:         // Parse params as serde_json::Value array.
108:         let params: serde_json::Value = match serde_json::from_str(params_json) {
109:             Ok(v) => v,
110:             Err(e) => return json_error(&format!("invalid params JSON: {}", e)),
111:         };
112: 
113:         // We use the rovs_ovsdb::Client::transact_raw or similar.
114:         // Since rovs_ovsdb::Client exposes `transact(Value) -> Result<Value>`,
115:         // we forward directly.
116:         match client.transact(params).await {
117:             Ok(result) => match serde_json::to_string(&result) {
118:                 Ok(s) => s,
119:                 Err(e) => json_error(&format!("serialize result failed: {}", e)),
120:             },
121:             Err(e) => json_error(&format!("transact failed: {}", e)),
122:         }
123:     }
124: 
125:     /// One-way notify (fire-and-forget).
126:     async fn notify(&self, _method: &str, _params_json: &str) {
127:         // rovs-jsonrpc notify support — placeholder; most callers use transact.
128:         debug!("jsonrpc.notify (passthrough stub)");
129:     }
130: 
131:     /// List databases on the OVSDB server (JSON-RPC `list_dbs`).
132:     /// Returns a JSON array of database names.
133:     async fn list_dbs(&self) -> String {
134:         let mut guard = match self.state.get_ovsdb().await {
135:             Ok(g) => g,
136:             Err(e) => return json_error(&format!("OVSDB connect failed: {}", e)),
137:         };
138:         let client = match guard.as_mut() {
139:             Some(c) => c,
140:             None => return json_error("OVSDB client unavailable"),
141:         };
142:         match client.list_dbs().await {
143:             Ok(dbs) => serde_json::to_string(&dbs)
144:                 .unwrap_or_else(|e| json_error(&format!("serialize result failed: {}", e))),
145:             Err(e) => json_error(&format!("list_dbs failed: {}", e)),
146:         }
147:     }
148: 
149:     /// Return the connected database's schema (cached from the OVSDB
150:     /// `get_schema` fetch at connect time). JSON-encoded `DbSchema`.
151:     async fn get_schema(&self) -> String {
152:         let guard = match self.state.get_ovsdb().await {
153:             Ok(g) => g,
154:             Err(e) => return json_error(&format!("OVSDB connect failed: {}", e)),
155:         };
156:         let client = match guard.as_ref() {
157:             Some(c) => c,
158:             None => return json_error("OVSDB client unavailable"),
159:         };
160:         match client.schema() {
161:             Some(schema) => serde_json::to_string(schema)
162:                 .unwrap_or_else(|e| json_error(&format!("serialize schema failed: {}", e))),
163:             None => json_error("schema not yet fetched"),
164:         }
165:     }
166: 
167:     /// Return next JSON-RPC request id (monotonic counter).
168:     async fn next_id(&self) -> u64 {
169:         // Simplistic id counter.  In full rovs-jsonrpc this is per-connection.
170:         1
171:     }
172: 
173:     /// Send raw JSON-RPC message string, return response string.
174:     async fn send_message(&self, msg: &str) -> String {
175:         debug!("jsonrpc.send_message len={}", msg.len());
176:         match serde_json::from_str::<serde_json::Value>(msg) {
177:             Ok(req) => {
178:                 let mut guard = match self.state.get_ovsdb().await {
179:                     Ok(g) => g,
180:                     Err(e) => return json_error(&format!("connect failed: {}", e)),
181:                 };
182:                 let client = match guard.as_mut() {
183:                     Some(c) => c,
184:                     None => return json_error("client unavailable"),
185:                 };
186:                 match client.transact(req).await {
187:                     Ok(r) => {
188:                         serde_json::to_string(&r).unwrap_or_else(|e| json_error(&e.to_string()))
189:                     }
190:                     Err(e) => json_error(&e.to_string()),
191:                 }
192:             }
193:             Err(e) => json_error(&format!("invalid JSON: {}", e)),
194:         }
195:     }
196: 
197:     /// Receive raw JSON-RPC message string.
198:     async fn recv_message(&self) -> String {
199:         // rovs-jsonrpc recv is async-stream oriented; stub for now.
200:         String::new()
201:     }
202: 
203:     /// Poll pending notifications.
204:     async fn has_pending_notifications(&self) -> bool {
205:         false
206:     }
207: 
208:     /// Count pending notifications.
209:     async fn pending_notification_count(&self) -> u64 {
210:         0
211:     }
212: 
213:     /// Pop one notification.
214:     async fn pop_notification(&self) -> String {
215:         String::new()
216:     }
217: 
218:     /// Drain all notifications.
219:     async fn drain_notifications(&self) -> String {
220:         "[]".to_string()
221:     }
222: 
223:     /// Open a new named stream / monitor.
224:     async fn new_stream(&self, stream: &str) -> String {
225:         debug!("jsonrpc.new_stream stream={}", stream);
226:         format!("{{\"stream\":\"{}\"}}", stream)
227:     }
228: 
229:     /// Daemon + connection status JSON.
230:     async fn status(&self) -> String {
231:         let connected = self.state.ovsdb.lock().await.is_some();
232:         format!(
233:             "{{\"connected\":{},\"socket_path\":\"{}\",\"version\":\"{}\"}}",
234:             connected,
235:             self.state.socket_path,
236:             env!("CARGO_PKG_VERSION")
237:         )
238:     }
239: }
240: 
241: fn json_error(msg: &str) -> String {
242:     serde_json::json!({"error": msg}).to_string()
243: }
244: 
245: // ── OpenFlow object (/org/opdbus/rovs/openflow) ─────────────────────────────
246: 
247: /// D-Bus service proxying raw `rovs-openflow` primitives via `rovs_transport::Address`
248: /// and `rovs_openflow::VConn`.
249: pub struct OpenFlowService {
250:     state: DaemonState,
251: }
252: 
253: impl OpenFlowService {
254:     pub fn new(state: DaemonState) -> Self {
255:         Self { state }
256:     }
257: }
258: 
259: #[interface(name = "org.opdbus.rovs.openflow")]
260: impl OpenFlowService {
261:     /// Connect to a switch at `addr` (e.g. `"tcp:127.0.0.1:6653"`).
262:     ///
263:     /// `addr` is parsed by `rovs_transport::Address::from_str` which supports:
264:     /// - `unix:/path/to/socket`
265:     /// - `tcp:host:port`
266:     /// - `ssl:host:port`
267:     ///
268:     /// Returns JSON `{"conn_id":N}` or `{"error":"..."}`.
269:     async fn connect(&self, addr: &str) -> String {
270:         debug!("openflow.connect addr={}", addr);
271: 
272:         let address = match addr.parse::<Address>() {
273:             Ok(a) => a,
274:             Err(e) => return json_error(&format!("bad address: {}", e)),
275:         };
276: 
277:         match rovs_openflow::VConn::connect(&address).await {
278:             Ok(vconn) => {
279:                 let id = self.state.alloc_of_id().await;
280:                 self.state.of_conns.lock().await.insert(id, vconn);
281:                 serde_json::json!({"conn_id": id}).to_string()
282:             }
283:             Err(e) => json_error(&format!("connect failed: {}", e)),
284:         }
285:     }
286: 
287:     /// Return negotiated OpenFlow version JSON.
288:     async fn version(&self, conn_id: u64) -> String {
289:         let mut conns = self.state.of_conns.lock().await;
290:         match conns.get_mut(&conn_id) {
291:             Some(vconn) => {
292:                 let ver = vconn.version();
293:                 serde_json::json!({"version": format!("{:?}", ver)}).to_string()
294:             }
295:             None => json_error("unknown conn_id"),
296:         }
297:     }
